const documentKinds=[{"key":"proposal","name":"Proposal","desc":"Latar belakang, scope, timeline, biaya, dan manfaat"},{"key":"brd","name":"BRD","desc":"Kebutuhan bisnis, proses, dan stakeholder"},{"key":"prd","name":"PRD","desc":"Tujuan produk, fitur, dan acceptance criteria"},{"key":"fsd","name":"FSD","desc":"Arsitektur, fungsi, data, integrasi, dan skenario uji"},{"key":"requirements","name":"Requirement Gathering","desc":"Stakeholder, RACI, elicitation, dan kebutuhan"},{"key":"presentation","name":"Presentasi","desc":"Ringkasan studi kasus dalam PDF dan PowerPoint"}];
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function visual(kind){
  const start='<svg viewBox="0 0 320 170" fill="none" aria-hidden="true" focusable="false">';
  const end='</svg>';
  const doc=(x,y,fill="#fffefa")=>`<rect x="${x}" y="${y}" width="53" height="68" rx="5" fill="${fill}" stroke="#8f9b87"/><path d="M${x+12} ${y+20}h27m-27 12h27m-27 12h18" stroke="#a2ae95" stroke-width="2"/>`;
  switch(kind){
    case "procurement":return start+'<path d="M79 91h162" stroke="#89977a" stroke-width="2"/><path d="m136 86 7 5-7 5m76-10 7 5-7 5" stroke="#52664d" stroke-width="1.5"/><rect x="26" y="65" width="67" height="52" rx="8" fill="#fffefa" stroke="#91a182"/><rect x="126" y="46" width="67" height="73" rx="8" fill="#233b33"/><rect x="226" y="65" width="67" height="52" rx="8" fill="#fffefa" stroke="#91a182"/><text x="59" y="97" text-anchor="middle" fill="#233b33" font-size="16">RO</text><text x="159" y="89" text-anchor="middle" fill="#e1ecb3" font-size="18">PO</text><text x="260" y="97" text-anchor="middle" fill="#233b33" font-size="16">GR</text><text x="159" y="139" text-anchor="middle" fill="#64765a" font-size="8" letter-spacing="1.5">ALUR PROCUREMENT</text>'+end;
    case "approval":return start+'<g transform="rotate(-7 119 83)">'+doc(69,47)+'</g><path d="M132 82h55" stroke="#b58c71" stroke-width="1.5" stroke-dasharray="4 4"/><rect x="179" y="62" width="91" height="48" rx="7" fill="#fffefa" stroke="#b2947f"/><circle cx="201" cy="86" r="12" fill="#e1ecb3"/><path d="m196 86 4 4 7-8" stroke="#233b33" stroke-width="1.7"/><path d="M222 80h33m-33 12h24" stroke="#adb09d" stroke-width="2"/><text x="160" y="141" text-anchor="middle" fill="#8b6a54" font-size="8" letter-spacing="1.4">CATAT · APPROVAL · STATUS</text>'+end;
    case "learning":return start+'<path d="M79 65h66v30h55m-121 17h66V95" stroke="#8fa16d" stroke-width="1.5"/><rect x="36" y="46" width="69" height="32" rx="16" fill="#fffefa" stroke="#b2bf92"/><rect x="25" y="96" width="81" height="32" rx="16" fill="#fffefa" stroke="#b2bf92"/><text x="70" y="66" text-anchor="middle" fill="#5f7048" font-size="10">Katalog</text><text x="66" y="116" text-anchor="middle" fill="#5f7048" font-size="10">Profesi</text><circle cx="152" cy="95" r="14" fill="#233b33"/><path d="m146 95 4 4 8-8" stroke="#e1ecb3" stroke-width="1.5"/><g transform="rotate(5 240 87)">'+doc(211,48)+ '</g><text x="240" y="141" text-anchor="middle" fill="#65764e" font-size="8" letter-spacing="1">MATERI RELEVAN</text>'+end;
    case "documents":return start+doc(48,53)+doc(91,43)+doc(134,53)+'<path d="M198 88h26m-7-5 7 5-7 5" stroke="#7f9592" stroke-width="1.5"/><rect x="236" y="58" width="48" height="62" rx="5" fill="#233b33"/><path d="M247 75h25m-25 12h25m-25 12h18" stroke="#dce6ce" stroke-width="2"/>'+end;
    case "delivery":return start+doc(62,45)+'<path d="M133 81h48m-7-5 7 5-7 5" stroke="#ab997c" stroke-width="1.5"/><rect x="195" y="45" width="64" height="80" rx="5" fill="#fffefa" stroke="#9b987f"/><path d="M207 64h39m-39 12h39m-39 12h24" stroke="#a1a18b" stroke-width="2"/><circle cx="249" cy="117" r="16" fill="#233b33"/><path d="m242 117 5 5 9-10" stroke="#e1ecb3" stroke-width="1.8"/>'+end;
    case "location":return start+'<path d="m48 65 73-24 77 29 77-27v83l-77 23-77-28-73 24V65Z" fill="#fffefa" stroke="#aba0aa"/><path d="M121 41v80m77-51v79" stroke="#d5cbd3"/><path d="m64 102 33-8 50 9 21-16 33 12 52-16" stroke="#c9bec9" stroke-width="2" stroke-dasharray="4 4"/><path d="M182 69c0 15-20 32-20 32s-20-17-20-32a20 20 0 1 1 40 0Z" fill="#233b33"/><circle cx="162" cy="68" r="7" fill="#e1ecb3"/>'+end;
    case "chart":return start+'<rect x="46" y="35" width="229" height="107" rx="7" fill="#fffefa" stroke="#a7af9c"/><path d="M66 60h188M66 86h188M66 112h188" stroke="#e2e6da"/><path d="m66 114 27-18 21 5 26-29 24 11 27-30 24 9" stroke="#233b33" stroke-width="2.5"/><path d="m215 62 18 10 20-27" stroke="#ca4c2b" stroke-width="2.5" stroke-dasharray="5 4"/><circle cx="215" cy="62" r="4" fill="#ca4c2b"/>'+end;
    case "leaf":return start+'<rect x="84" y="33" width="151" height="113" rx="9" fill="#fffefa" stroke="#a2b197"/><path d="M118 116c-11-42 6-58 58-62 4 39-7 66-41 60" fill="#c2d3a5" stroke="#748c61" stroke-width="1.5"/><path d="m118 128 47-61m-28 36 1-21m7 11 18-4" stroke="#748c61" stroke-width="1.5"/><path d="M74 54V30h25m126 0h23v24M74 124v24h25m126 0h23v-24" stroke="#233b33" stroke-width="2"/>'+end;
    default:return start+end;
  }
}

const grid=$("#project-grid");
projects.forEach((p,i)=>{
  const card=document.createElement("article");card.className="project-card";card.dataset.id=p.id;card.dataset.category=p.category;
  card.innerHTML=`<div class="project-visual tone-${p.tone}"><span class="project-number">${String(i+1).padStart(2,"0")} / PROYEK</span>${p.featured?'<span class="featured-label">PILIHAN PORTOFOLIO</span>':""}${p.documents.length?'<span class="document-ready-badge">Dokumentasi tersedia</span>':""}${visual(p.visual)}</div><div class="project-body"><p class="project-category">${escapeHTML(p.type)}</p><h3>${escapeHTML(p.title)}</h3><p class="project-description">${escapeHTML(p.intro)}</p><div class="project-tags">${p.tools.slice(0,3).map(t=>`<span>${escapeHTML(t)}</span>`).join("")}</div><button type="button" class="project-open" data-open="${p.id}" aria-label="Lihat proyek ${escapeHTML(p.title)}">Lihat proyek <svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></button></div>`;
  grid.append(card);
});

let activeFilter="all";
function applyFilters(){
  const term=$("#project-search").value.trim().toLocaleLowerCase("id");let shown=0;
  projects.forEach(p=>{const match=(activeFilter==="all"||p.category===activeFilter)&&[p.title,p.original,p.type,p.intro,...p.tools].join(" ").toLocaleLowerCase("id").includes(term);const card=grid.querySelector(`[data-id="${p.id}"]`);card.hidden=!match;if(match)shown++;});
  $("#result-count").textContent=`Menampilkan ${shown} dari ${projects.length} proyek`;$("#empty-state").hidden=shown!==0;
}
document.querySelectorAll(".filter").forEach(btn=>btn.addEventListener("click",()=>{activeFilter=btn.dataset.filter;document.querySelectorAll(".filter").forEach(b=>{b.classList.toggle("active",b===btn);b.setAttribute("aria-pressed",String(b===btn));});applyFilters();}));
$("#project-search").addEventListener("input",applyFilters);
$("#reset-search").addEventListener("click",()=>{$("#project-search").value="";document.querySelector('[data-filter="all"]').click();$("#project-search").focus();});

const dialog=$("#project-dialog");const tabs=[ $("#tab-summary"),$("#tab-documents") ];let trigger=null;
function selectTab(idx,focus=false,updateURL=true){
  tabs.forEach((tab,i)=>{tab.setAttribute("aria-selected",String(idx===i));tab.tabIndex=idx===i?0:-1;$("#"+tab.getAttribute("aria-controls")).hidden=idx!==i;});
  if(focus)tabs[idx].focus();
  if(updateURL&&dialog.open){const url=new URL(location.href);if(idx===1)url.searchParams.set("tab","documents");else url.searchParams.delete("tab");history.replaceState({project:url.searchParams.get("project")},"",url);}
}
tabs.forEach((tab,idx)=>{tab.addEventListener("click",()=>selectTab(idx));tab.addEventListener("keydown",e=>{if(["ArrowLeft","ArrowRight","Home","End"].includes(e.key)){e.preventDefault();selectTab(e.key==="Home"?0:e.key==="End"?1:1-idx,true);}});});
function visibleProjectDocuments(project){
  return project.documents.filter(doc=>doc.kind!=="case-study");
}
function renderProjectFacts(project){
  const facts=$("#dialog-facts");facts.replaceChildren();facts.hidden=!project.facts;
  for(const fact of project.facts||[]){const item=document.createElement("div"),term=document.createElement("dt"),value=document.createElement("dd");term.textContent=fact.label;value.textContent=fact.label==="Dokumentasi"?`${visibleProjectDocuments(project).length} jenis dokumen`:fact.value;if(fact.detail){const detail=document.createElement("small");detail.textContent=fact.detail;value.append(detail);}item.append(term,value);facts.append(item);}
  const simulation=$("#dialog-simulation");simulation.hidden=!project.simulation;
  $("#simulation-description").textContent=project.simulation||"";
  $("#simulation-metrics").replaceChildren(...(project.simulationMetrics||[]).map(metric=>{const item=document.createElement("div"),value=document.createElement("strong"),label=document.createElement("span");value.textContent=metric.value;label.textContent=metric.label;item.append(value,label);return item;}));
}
// Visibility settings affect the UI only; document files and download URLs remain intact.
const documentDownloadUI={editable:false,bundle:false};
function renderDocuments(project){
  const documents=visibleProjectDocuments(project);
  $(".tab-count").textContent=documents.length;
  $("#docs-panel-intro").textContent=project.documentsIntro?.replace("presentasi dan studi kasus","presentasi")||(documents.length
    ?`Versi ${project.documentVersion} · Pilih Baca PDF untuk membaca langsung di website. Dokumen merupakan rekonstruksi portofolio; biaya dan manfaat memakai data dummy. Bukti UAT serta contoh penggunaan internal tidak ditampilkan.`
    :"Ringkasan proyek sudah tersedia. Dokumen pendukung akan ditambahkan saat materinya siap.");
  const visibleKinds=documents.length
    ?documents.map(doc=>({key:doc.kind,name:doc.name,desc:doc.desc||(documentKinds.find(kind=>kind.key===doc.kind)||{}).desc||"Dokumentasi proyek"}))
    :documentKinds;
  $("#document-list").replaceChildren(...visibleKinds.map(kind=>{
    const row=document.createElement("div");row.className="document-row";
    const doc=documents.find(item=>item.kind===kind.key),info=document.createElement("span"),description=document.createElement("small");
    info.textContent=kind.name;description.textContent=kind.key==="presentation"?"Ringkasan proyek, diagram, dan tabel dalam format PDF.":kind.desc;info.append(description);row.append(info);
    if(doc){
      const actions=document.createElement("div");actions.className="document-actions";
      const preview=document.createElement("a");preview.href=doc.preview;preview.textContent="Baca PDF";preview.setAttribute("aria-label",`Baca PDF ${kind.name} untuk proyek ${project.title} langsung di website`);
      const download=document.createElement("a");download.href=doc.download;download.download=doc.download.split("/").pop();download.textContent=`Unduh ${doc.format}`;download.setAttribute("aria-label",`Unduh ${kind.name} untuk proyek ${project.title} dalam format ${doc.format}`);
      download.hidden=!documentDownloadUI.editable&&/\.(docx?|pptx?)(?:[?#]|$)/i.test(doc.download);
      actions.append(preview,download);row.append(actions);
    }else{const button=document.createElement("button");button.type="button";button.disabled=true;button.textContent="Belum tersedia";row.append(button);}
    return row;
  }));
  const bundle=$("#document-bundle");bundle.hidden=!documentDownloadUI.bundle||!project.bundle;
  $("#document-bundle-description").textContent=project.bundleDescription||"Versi 1.3 · Word, PowerPoint, PDF presentasi, dan 6 diagram SVG · ±14,1 MB";
  const bundleLink=$("#document-bundle-link");if(project.bundle){bundleLink.href=project.bundle;bundleLink.download=project.bundle.split("/").pop();}else bundleLink.removeAttribute("href");
  const architecture=$("#project-architecture");architecture.hidden=!project.architecture;
  const architectureImage=$("#architecture-image"),architectureLink=$("#architecture-link");
  if(project.architecture){
    architectureImage.src=project.architecture;architectureLink.href=project.architecture;
    architectureImage.alt=project.architectureAlt||"Diagram hubungan Power Apps, Power Automate, Teams, SharePoint, UiPath, dan email dalam otomasi procurement";
    architectureLink.setAttribute("aria-label",`Buka diagram arsitektur ${project.title} dalam ukuran penuh`);
    $("#architecture-caption").textContent=project.architectureCaption||"SharePoint menampung monitoring dan hasil dokumen. Detail integrasi serta kontrol teknis adalah rekonstruksi usulan. Klik diagram untuk memperbesar.";
  }else{architectureImage.removeAttribute("src");architectureLink.removeAttribute("href");architectureImage.alt="";$("#architecture-caption").textContent="";}
}
function openProject(id,updateURL=true,initialTab=0){
  const project=projects.find(item=>item.id===id);if(!project)return;
  trigger=document.activeElement;
  $("#dialog-category").textContent=project.type;$("#dialog-kicker").textContent=project.original;$("#dialog-title").textContent=project.title;$("#dialog-intro").textContent=project.intro;
  $("#dialog-tags").replaceChildren(...project.tools.map(tool=>{const el=document.createElement("span");el.textContent=tool;return el;}));
  $("#dialog-context").textContent=project.context;$("#dialog-solution").textContent=project.solution;$("#dialog-value").textContent=project.value;$("#dialog-value-heading").textContent=project.research?"Manfaat yang dituju":"Manfaat bisnis";$("#dialog-note").textContent=project.note;
  renderProjectFacts(project);renderDocuments(project);selectTab(initialTab,false,false);
  if(!dialog.open)dialog.showModal();document.body.classList.add("dialog-open");dialog.scrollTop=0;$(".dialog-scroll").scrollTop=0;
  if(updateURL){const url=new URL(location.href);url.searchParams.set("project",project.id);if(initialTab===1)url.searchParams.set("tab","documents");else url.searchParams.delete("tab");history.pushState({project:project.id},"",url);}
}
document.addEventListener("click",event=>{const button=event.target.closest("[data-open]");if(button){event.preventDefault();openProject(button.dataset.open,true,button.dataset.tab==="documents"?1:0);}});
$("#close-dialog").addEventListener("click",()=>dialog.close());
dialog.addEventListener("click",e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
dialog.addEventListener("close",()=>{document.body.classList.remove("dialog-open");const url=new URL(location.href);url.searchParams.delete("project");url.searchParams.delete("tab");history.replaceState({},"",url);if(trigger instanceof HTMLElement&&trigger.isConnected)trigger.focus();});
window.addEventListener("popstate",()=>{const id=new URL(location.href).searchParams.get("project");if(id)openProject(id,false,new URL(location.href).searchParams.get("tab")==="documents"?1:0);else if(dialog.open)dialog.close();});
const initialProject=new URL(location.href).searchParams.get("project");if(initialProject)openProject(initialProject,false,new URL(location.href).searchParams.get("tab")==="documents"?1:0);

const menu=$(".menu-toggle");const nav=$("#nav");menu.addEventListener("click",()=>{const expanded=menu.getAttribute("aria-expanded")==="true";menu.setAttribute("aria-expanded",String(!expanded));nav.classList.toggle("open",!expanded);});
nav.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{menu.setAttribute("aria-expanded","false");nav.classList.remove("open");}));
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&nav.classList.contains("open")){nav.classList.remove("open");menu.setAttribute("aria-expanded","false");menu.focus();}});
$("#year").textContent=new Date().getFullYear();
